  ('606aa7bc-4a0e-40f9-88ec-0efea841aa29', '3010cd08-09bf-42c9-b620-494ddb6f0f10', null, 'topic'::public.curated_course_node_type, 'Engineering Calculation Framework, Units, and Dimensions', 'This opening topic builds the calculation discipline chemical engineers need before touching process balances. Students learn to make quantities, units, basis choices, and estimates explicit so later balance work is reliable.', 0),
